#!/usr/bin/env python3
"""Validate report.pdf: page 1 is the cover (title + current date), original pages intact."""

import sys
from datetime import date

from pypdf import PdfReader

REPORT = "report.pdf"
TITLE = "Annual Financial Report"
date_str = date.today().strftime("%B %d, %Y")


def main() -> int:
    reader = PdfReader(REPORT)
    print(f"Total pages: {len(reader.pages)}")
    ok = True
    for i, page in enumerate(reader.pages, start=1):
        text = (page.extract_text() or "").replace("\n", " ")
        print(f"--- Page {i} ---")
        print(text[:300])
        if i == 1:
            if TITLE not in text:
                print("FAIL: title missing on page 1", file=sys.stderr)
                ok = False
            if date_str not in text:
                print(f"FAIL: date '{date_str}' missing on page 1", file=sys.stderr)
                ok = False
        else:
            if not text.strip():
                print(f"WARN: page {i} has no extractable text", file=sys.stderr)
    if ok:
        print("VALIDATION OK: cover page present with title and current date; report content intact.")
    return 0 if ok else 1


if __name__ == "__main__":
    sys.exit(main())

